-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): scal.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/scal.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- ADVANCED
--   fitted_nw was graded on the noise-free 13-row grid sampled from the design
--   Corey set, so the fit recovers its own plant (2.4999999999999996) and 2.5
--   written from the design table, or the DesignExplorer tile labelled 'Fitted
--   nw (plant 2.5)', passed without fitting anything (B5 finding 4). The
--   replacement fits the SAME 13 rows with every kr rounded to the three
--   decimals a lab sheet prints (Sw unchanged, endpoints fixed from the table,
--   the same fitCoreyToKrTable call). The rounding moves nw to
--   2.4318603318221883 (scalLab.js fitPrintedLabGrid, 24 points, converged). The
--   DesignExplorer prints it in a NON-default mode, 'Fit the printed grid (kr to
--   3 dp)', at 9 significant figures (2.43186033). Tol stays 0.001: the plant
--   2.5 misses by 0.068, the noise-free fit by 0.068, the oil exponent of the
--   same fit (2.00765) by 0.42, and fits on a 2 dp or 4 dp grid (2.49675,
--   2.50045) by more than 0.06, so each fails; the 9 significant figure reading
--   passes by 1e-9.
--   RE-KEY fitted_nw (expected 2.4999999999999996, tol 0.001)
--       -> fitted_nw_printed_grid 'Fitted water Corey exponent nw, kr printed to 3 dp' -, expected 2.4318603318221883, tol 0.001
--   PROMPT was: Fit the 13-row lab relative permeability grid (Sw 0.35 to 0.75
--   in twelve equal steps, Swirr 0.25 given) with fixed endpoints taken from the
--   table and report the fitted water exponent.
--   PROMPT now: Fit the 13-row lab relative permeability grid (Sw 0.35 to 0.75
--   in twelve equal steps, Swirr 0.25 given) as the lab sheet prints it, every
--   kr rounded to three decimals, with fixed endpoints taken from the table and
--   report the fitted water exponent.
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves: scal/advanced. Before
-- it writes, the file counts academy_capstone_attempts on each and REFUSES if
-- any exist, unless D5 allowlists that tier with the exact attempt ids
-- (allowlist: empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- scal / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'scal' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 scal refused: scal/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '6c23428092a75bce1841682c23f1a834' and fields = '[{"key": "fitted_nw", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw", "expected": 2.4999999999999996}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb then 'old'
              when md5(prompt) = '2f1bd16e772b7aab505fc5a0f04d4c6d' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb then 'new'
              when md5(prompt) = 'c8e94f82b3e55c070b52274fa9dcfc6f' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'scal' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w1 scal refused: scal/advanced matches neither its published form (prompt md5 6c23428092a75bce1841682c23f1a834) nor its W1 form (prompt md5 2f1bd16e772b7aab505fc5a0f04d4c6d), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 scal: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 scal refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'scal' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'scal/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'scal/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 scal refused: scal/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 scal: scal/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 scal refused: scal/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Fit the 13-row lab relative permeability grid (Sw 0.35 to 0.75 in twelve equal steps, Swirr 0.25 given) as the lab sheet prints it, every kr rounded to three decimals, with fixed endpoints taken from the table and report the fitted water exponent. Average the three Ekene plug J-curves at the true Swirr 0.25 and report the refitted coefficient a, which drifts off the design 0.25 through the log-linear resampling. Then design the flood on the Ekene sand: the displacement efficiency at breakthrough for the dip case (k 250 md, cross-section 20000 ft2, total rate 2000 rb/d, water gravity 1.03, oil gravity from API 32) displacing updip at plus 10 degrees and again downdip at minus 10 degrees, the polymer screening case at a water viscosity multiplier of 4, and the height-averaged water saturation over the crest column from the composite trapezoid with 2000 intervals between the contact and the crest.',
           fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb
     where app_slug = 'scal' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 scal refused: scal/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '2f1bd16e772b7aab505fc5a0f04d4c6d' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb)
        or (md5(prompt) = 'c8e94f82b3e55c070b52274fa9dcfc6f' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb) from public.academy_capstones where app_slug = 'scal' and tier = 'advanced' and active) is not true then
    raise exception 'w1 scal refused: scal/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 scal: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
